<?php
declare(strict_types=1);
require_once __DIR__ . '/app/bootstrap.php';
$currentPage='reviews.php';$pageTitle='Client Reviews';$metaDescription='Read and share feedback about your experience with '.setting('site_name','Tiba Quip Africa').'.';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{check_csrf();if(($_POST['action']??'')!=='site_review')throw new RuntimeException('Unable to submit this review.');submit_site_review($_POST);track('site_review_submitted');$_SESSION['site_review_pending_notice']=true;redirect('reviews.php#write-review');}catch(RuntimeException $e){$error=$e->getMessage();}}
$reviewPendingNotice=!empty($_SESSION['site_review_pending_notice']);unset($_SESSION['site_review_pending_notice']);
$reviewPage=max(1,(int)($_GET['page']??1));$reviewsAvailable=true;try{$summary=site_review_summary();$reviews=rows('SELECT author_name,rating,body,created_at FROM site_reviews WHERE status="published" ORDER BY created_at DESC,id DESC LIMIT 12 OFFSET '.(($reviewPage-1)*12));$ownReview=row('SELECT author_name,email,rating,body,status FROM site_reviews WHERE reviewer_key=?',[site_review_identity()]);}catch(RuntimeException $e){$reviewsAvailable=false;$summary=['average'=>0,'count'=>0];$reviews=[];$ownReview=null;$error=$error?:$e->getMessage();}track('page_view');
require __DIR__ . '/overall/head.php';require __DIR__ . '/overall/header.php';
?>
<main class="tq-company-reviews"><section class="tq-review-hero"><div class="container"><div><p class="tq-review-kicker">Tiba Quip Africa</p><h1>Client reviews</h1><p>Read feedback from clients and share your experience with our products and service.</p></div><a class="theme-btn" href="#write-review">Write a review <i class="far fa-pen"></i></a></div></section><section class="py-90"><div class="container"><div class="tq-company-rating-card"><div class="tq-company-rating-score"><strong><?= $summary['count'] ? h(number_format($summary['average'],1)) : '—' ?></strong><span>out of 5</span></div><div><div class="tq-company-stars" aria-label="<?= $summary['count'] ? h(number_format($summary['average'],1).' out of 5 stars') : 'No ratings yet' ?>"><?= review_stars($summary['average']) ?></div><h2><?= $summary['count'] ? number_format($summary['count']).' client '.($summary['count']===1?'review':'reviews'):'Be the first client to review us' ?></h2><p>Reviews are submitted by clients and published after approval.</p></div><a class="tq-review-text-link" href="#write-review">Share your experience</a></div><div class="row g-4"><div class="col-lg-7"><section class="tq-company-review-list" aria-label="Published client reviews"><h2>What clients say</h2><?php if(!$reviews): ?><div class="tq-company-review-empty"><i class="far fa-comment-heart"></i><h3>No published reviews yet</h3><p>Your feedback can help other clients understand what to expect from <?= h(setting('site_name')) ?>.</p></div><?php endif; ?><?php foreach($reviews as $review): ?><article class="tq-company-review"><div class="tq-company-review-head"><span class="tq-review-avatar" aria-hidden="true"><?= h(mb_strtoupper(mb_substr($review['author_name'],0,1))) ?></span><div><strong><?= h($review['author_name']) ?></strong><time datetime="<?= h(date('Y-m-d',strtotime($review['created_at']))) ?>"><?= h(date('j M Y',strtotime($review['created_at']))) ?></time></div><span class="tq-company-review-stars" aria-label="<?= (int)$review['rating'] ?> out of 5 stars"><?= review_stars((float)$review['rating']) ?></span></div><p><?= nl2br(h($review['body'])) ?></p></article><?php endforeach; ?><?php if($summary['count']>12): ?><nav class="tq-review-pages" aria-label="Client review pages"><?php if($reviewPage>1): ?><a href="<?= url('reviews.php?page='.($reviewPage-1)) ?>">Previous reviews</a><?php endif; ?><?php if($reviewPage*12<$summary['count']): ?><a href="<?= url('reviews.php?page='.($reviewPage+1)) ?>">More reviews</a><?php endif; ?></nav><?php endif; ?></section></div><div class="col-lg-5"><aside class="tq-company-review-form" id="write-review"><h2><?= $ownReview?'Update your review':'Rate your experience' ?></h2><p>Tell us about your overall experience with <?= h(setting('site_name')) ?>. Your email remains private.</p><?php if($error): ?><div class="alert alert-danger" role="alert"><?= h($error) ?></div><?php endif; ?><?php if($ownReview&&$ownReview['status']==='pending'): ?><div class="alert alert-info" role="status">Your current review is waiting for approval. You can update it below.</div><?php elseif($ownReview&&$ownReview['status']==='hidden'): ?><div class="alert alert-info" role="status">Your current review is not public. You can update and submit it again below.</div><?php endif; ?><form method="post" class="store-form" autocomplete="on"><?= csrf_field() ?><input type="hidden" name="action" value="site_review"><fieldset class="tq-rating-input"><legend>Your rating</legend><div><?php for($star=5;$star>=1;$star--): ?><input type="radio" id="site-review-star-<?= $star ?>" name="rating" value="<?= $star ?>" required <?= (int)($_POST['rating']??$ownReview['rating']??0)===$star?'checked':'' ?>><label for="site-review-star-<?= $star ?>" title="<?= $star ?> stars">★<span class="visually-hidden"><?= $star ?> <?= $star===1?'star':'stars' ?></span></label><?php endfor; ?></div></fieldset><div class="row"><div class="col-md-6"><label for="site-review-name">Your name</label><input id="site-review-name" name="name" required maxlength="190" autocomplete="name" value="<?= h($_POST['name']??$ownReview['author_name']??user()['name']??'') ?>"></div><div class="col-md-6"><label for="site-review-email">Email (private)</label><input id="site-review-email" name="email" type="email" maxlength="190" autocomplete="email" value="<?= h($_POST['email']??$ownReview['email']??user()['email']??'') ?>"></div></div><label for="site-review-body">Your review</label><textarea id="site-review-body" name="review" required maxlength="2000" rows="6" placeholder="How was your experience with Tiba Quip Africa?"><?= h($_POST['review']??$ownReview['body']??'') ?></textarea><div class="tq-review-honeypot" aria-hidden="true"><label>Website<input name="website" tabindex="-1" autocomplete="off"></label></div><button class="theme-btn" type="submit">Submit review <i class="far fa-arrow-right"></i></button></form></aside></div></div></div></section></main>
<?php require __DIR__ . '/overall/footer.php';require __DIR__ . '/overall/scripts.php'; ?>
